const profesionales = $('Supabase - Profesional').all().map(item => item.json);

const formateados = profesionales.map((p, index) => {
  return `${index + 1}. ${p.nombre}${p.especialidad ? ' - ' + p.especialidad : ''}`;
});

const mensajeTexto = `¿Con qué profesional te gustaría atenderte?\n\n${formateados.join('\n')}\n\nRespondé con el número.`;

return [{
  json: {
    profesionales_disponibles: profesionales,
    output: mensajeTexto
  }
}];

const mensajeUsuario = $('Input').first().json.body.mensaje.trim();
const contexto = $json.contexto; // array de profesionales, viene del nodo Postgres

const numeroElegido = parseInt(mensajeUsuario, 10);

if (isNaN(numeroElegido) || numeroElegido < 1 || numeroElegido > contexto.length) {
  return [{
    json: {
      valido: false,
      output: `No entendí tu respuesta. Por favor, respondé con un número del 1 al ${contexto.length} según los profesionales que te ofrecí.`
    }
  }];
}

const profesionalElegido = contexto[numeroElegido - 1];

return [{
  json: {
    valido: true,
    profesional_id: profesionalElegido.id,
    profesional: profesionalElegido
  }
}];

const profesional = $('Code in JavaScript - Validar Profesional').first().json.profesional;
const turnosOcupados = $('Supabase - Turnos').all().map(item => item.json).filter(t => t.start_time);

const duracion = profesional.duracion_consulta_minutes;
const slots = [];
const hoy = new Date();

for (let dia = 0; dia < 7; dia++) {
  const fecha = new Date(hoy);
  fecha.setDate(hoy.getDate() + dia);
  const diaSemana = fecha.getDay();

  if (diaSemana === 0 && !profesional.atiende_domingos) continue;
  if (diaSemana === 6 && !profesional.atiende_sabados) continue;

  const [horaInicio] = profesional.hora_inicio.split(':').map(Number);
  const [horaFin] = profesional.hora_fin.split(':').map(Number);

  for (let hora = horaInicio; hora < horaFin; hora += duracion / 60) {
    const slotStart = new Date(fecha);
    slotStart.setHours(Math.floor(hora), (hora % 1) * 60, 0, 0);
    const slotEnd = new Date(slotStart.getTime() + duracion * 60000);

    const ocupado = turnosOcupados.some(t => {
      const tStart = new Date(t.start_time);
      const tEnd = new Date(tStart.getTime() + duracion * 60000);
      return slotStart < tEnd && slotEnd > tStart;
    });

    if (!ocupado && slotStart > hoy) {
      slots.push(slotStart.toISOString());
    }
  }
}

const slotsElegidos = slots.slice(0, 5);

// Texto legible en español para cada slot
const formateados = slotsElegidos.map((iso, index) => {
  const fecha = new Date(iso);
  const diasSemana = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
  const diaNombre = diasSemana[fecha.getDay()];
  const diaMes = fecha.getDate();
  const mes = fecha.getMonth() + 1;
  const hora = fecha.getHours().toString().padStart(2, '0');
  const min = fecha.getMinutes().toString().padStart(2, '0');
  return `${index + 1}. ${diaNombre} ${diaMes}/${mes}, ${hora}:${min}`;
});

const mensajeTexto = `Estos son los horarios disponibles con ${profesional.nombre}:\n\n${formateados.join('\n')}\n\nRespondé con el número del horario que preferís.`;

return [{
  json: {
    profesional_id: profesional.id,
    horarios_disponibles: slotsElegidos,
    output: mensajeTexto
  }
}];

const mensajeUsuario = $('Input').first().json.body.mensaje.trim();
const contexto = $json.contexto; // viene del nodo Postgres: { profesional_id, horarios }
const horarios = contexto.horarios;

const numeroElegido = parseInt(mensajeUsuario, 10);

if (isNaN(numeroElegido) || numeroElegido < 1 || numeroElegido > horarios.length) {
  return [{
    json: {
      valido: false,
      output: `No entendí tu respuesta. Por favor, respondé con un número del 1 al ${horarios.length} según los horarios que te ofrecí.`
    }
  }];
}

const horarioElegido = horarios[numeroElegido - 1];

return [{
  json: {
    valido: true,
    horario_elegido: horarioElegido,
    profesional_id: contexto.profesional_id,
    output: '¡Perfecto! Para confirmar tu turno, decime tu nombre completo.'
  }
}];

const respuesta = $('Input').first().json.body.mensaje.trim().toLowerCase();
const confirmado = respuesta.includes('si') || respuesta.includes('sí');

// Traemos el turno_id guardado en el contexto de la conversación
const contexto = $json.contexto;

return [{
  json: {
    confirmado,
    turno_id: contexto.turno_id
  }
}];

