const mensajeUsuario = $('Input').first().json.body.mensaje.trim();
const contexto = $json.contexto; // { horario_elegido, profesional_id, profesional_nombre, paciente_nombre }
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (!emailRegex.test(mensajeUsuario)) {
  return [{
    json: {
      valido: false,
      output: 'Ese correo no parece válido. Por favor, escribilo de nuevo (ej: nombre@ejemplo.com).'
    }
  }];
}

return [{
  json: {
    valido: true,
    email: mensajeUsuario,
    contexto
  }
}];
